/**
 * Return whether possibly distinct array is sorted.
 *
 * @param {array} a - Input array which can only contain integers
 * @param {int} pos - The last element considered
 * @returns {boolean} True if the array is odd and sorted, otherwise false
 *
 * Example usage:
 *
 *      isOddPermutation([1, 2, 3]);
 * => true // The array is sorted and all numbers 1-3 are present
 *
 *      isOddPermutation([1, 3, 2]);
 * => false // The array is not sorted.
 *
 *      isOddPermutation([1, 2, 2]);
 * => false // The array is not sorted.
 *
 *      isOddPermutation([9, 9, 9]);
 * => false // The array is sorted but contains the same element.
 *
 *      isOddPermutation([1, 2, 9, 8, 3, 4, 5, 6, 7]);
 * => true // Element position can be out of order.
 *
 *      isOddPermutation([1, 2, 9, 8, 5, 4, 3, 7, 6]);
 * => false // 8 or 9 are missing
 */
function isOddPermutation(a) {
    if (typeof a.length !== 'number' || typeof a !== 'object') {
        throw new TypeError('Expected an array, got ' + (typeof a) + ' ' + String(a));
    }

    for(let j = 0; j < a.length; j++){
        if(a[j].valueOf() < 0)
            throw new RangeError('Values in array must be non-negative');
    }

    for (let i = 0; i < a.length; i++) {
        if (a[i] !== i + 1)
            return false;
    }

    return true;
}

